BEGIN;
update public.vihem_system_settings set value=jsonb_set(value,'{enabled}','false') where key='push_notification_dispatch';
create function pg_temp.expect(label text,ok boolean) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.reject(label text,statement text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;if not failed then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create temp table f(o uuid,o2 uuid,a uuid,s uuid,client uuid,client2 uuid,route uuid,op uuid,second uuid,t timestamptz);
do $$declare o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();r uuid:=gen_random_uuid();begin
 insert into public.vihem_organisations(id,name,slug) values(o,'QA Snow','snow-'||o),(o2,'QA Other Snow','snow-'||o2);
 insert into auth.users(id,email) values(a,a||'@example.invalid'),(s,s||'@example.invalid');
 insert into public.vihem_profiles(id,organisation_id,name,email,role,active) values(a,o,'Snow Admin',a||'@example.invalid','admin',true),(s,o,'Snow Staff',s||'@example.invalid','staff',true) on conflict(id) do update set organisation_id=excluded.organisation_id,role=excluded.role,active=true;
 insert into public.vihem_organisation_modules(organisation_id,module_key,enabled,settings) values(o,'snow',true,'{"admin_only":false}'),(o2,'snow',true,'{"admin_only":false}') on conflict(organisation_id,module_key) do update set enabled=true;
 insert into public.vihem_permission_grants(organisation_id,user_id,permission_key) values(o,s,'module.snow');
 insert into public.vihem_time_categories(organisation_id,key,label,active) values(o,'snow_plowing','Snöröjning',true),(o,'snow_sanding','Sandning',true) on conflict do nothing;
 insert into public.vihem_snow_clients(id,organisation_id,name) values(c,o,'SVEVIA VIRSERUM'),(c2,o2,'Other org client');
 insert into public.vihem_snow_routes(id,organisation_id,client_id,name,method,geometry) values(r,o,c,'Prio route','machine','{"type":"LineString","coordinates":[[15.58,57.31],[15.59,57.32]]}');
 insert into f values(o,o2,a,s,c,c2,r,gen_random_uuid(),gen_random_uuid(),now()-interval '20 minutes');
 perform set_config('request.jwt.claim.sub',s::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true);
end$$;
do $$declare other uuid:=gen_random_uuid();begin insert into auth.users(id,email) values(other,other||'@example.invalid');insert into public.vihem_profiles(id,organisation_id,name,email,role,active) select other,o2,'Other Organisation Driver',other||'@example.invalid','staff',true from f on conflict(id) do update set organisation_id=excluded.organisation_id,role='staff',active=true;end$$;
alter table f add column foreign_user uuid;update f set foreign_user=(select id from public.vihem_profiles where organisation_id=f.o2 limit 1);
grant select on f to authenticated;

update public.vihem_profiles set role='snow',snow_time_access=true where id=(select s from f);
insert into public.vihem_jour_shifts(organisation_id,duty_type,user_id,starts_at,ends_at) select o,'sno',s,'2026-11-02T00:00:00+01','2026-11-03T00:00:00+01' from f;
insert into public.vihem_jour_shifts(organisation_id,duty_type,user_id,starts_at,ends_at) select o,'sno',a,'2026-11-03T00:00:00+01','2026-11-04T00:00:00+01' from f;
insert into public.vihem_staff_absence_requests(organisation_id,user_id,absence_type,start_date,end_date,status,comment) select o,s,'vacation','2026-11-10','2026-11-10','approved','QA private reason' from f;
insert into public.vihem_staff_absence_requests(organisation_id,user_id,absence_type,start_date,end_date,status,comment) select o,a,'vacation','2026-11-11','2026-11-11','approved','QA other private reason' from f;
update public.vihem_organisation_modules set settings='{"admin_only":true}' where organisation_id=(select o from f) and module_key='snow';
set local role authenticated;
select pg_temp.reject('snow calendar remains blocked in admin pilot',$q$select public.vihem_snow_availability_snapshot('2026-11-01',30)$q$);
reset role;
-- Unlock only this rolled-back synthetic organisation, never the real pilot.
update public.vihem_organisation_modules set settings='{"admin_only":false}' where organisation_id=(select o from f) and module_key='snow';
set local role authenticated;
select pg_temp.expect('driver roster contains only self',public.vihem_snow_availability_snapshot('2026-11-01',30)->'people'->0->>'id'=(select s::text from f) and jsonb_array_length(public.vihem_snow_availability_snapshot('2026-11-01',30)->'people')=1);
select pg_temp.expect('driver jour contains only self',jsonb_array_length(public.vihem_snow_availability_snapshot('2026-11-01',30)->'shifts')=1 and public.vihem_snow_availability_snapshot('2026-11-01',30)->'shifts'->0->>'user_id'=(select s::text from f));
select pg_temp.expect('driver sees only own absence dates without private reason',jsonb_array_length(public.vihem_snow_availability_snapshot('2026-11-01',30)->'absences')=1 and public.vihem_snow_availability_snapshot('2026-11-01',30)->'absences'->0->>'user_id'=(select s::text from f) and not ((public.vihem_snow_availability_snapshot('2026-11-01',30)->'absences')::text like '%private reason%'));
select public.vihem_snow_availability_save(op,s,ARRAY['2026-11-01','2026-11-30']::date[],'available','[]','{"2026-11-01":0,"2026-11-30":0}') from f;
select public.vihem_snow_availability_save(op,s,ARRAY['2026-11-01','2026-11-30']::date[],'available','[]','{"2026-11-01":0,"2026-11-30":0}') from f;
select pg_temp.expect('own month boundaries saved once',(select count(*)=2 and max(revision)=1 from public.vihem_snow_availability));
select pg_temp.reject('driver cannot change admin',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L]::date[],%L,%L::jsonb,%L::jsonb)',gen_random_uuid(),a,'2026-11-02','available','[]','{"2026-11-02":0}')) from f;
select pg_temp.reject('driver cannot change foreign organisation',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L]::date[],%L,%L::jsonb,%L::jsonb)',gen_random_uuid(),foreign_user,'2026-11-02','available','[]','{"2026-11-02":0}')) from f;
reset role;
select set_config('request.jwt.claim.sub',a::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from f;
set local role authenticated;
select public.vihem_snow_availability_save(gen_random_uuid(),a,ARRAY['2026-11-02']::date[],'available','[]','{"2026-11-02":0}') from f;
select pg_temp.expect('admin retains full roster',jsonb_array_length(public.vihem_snow_availability_snapshot('2026-11-01',30)->'people')=2);
reset role;
select set_config('request.jwt.claim.sub',s::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true) from f;
set local role authenticated;
select pg_temp.expect('driver direct SELECT excludes other profiles days',(select count(*)=2 and bool_and(user_id=(select s from f)) from public.vihem_snow_availability));
select pg_temp.expect('driver snapshot days only own',not exists(select 1 from jsonb_array_elements(public.vihem_snow_availability_snapshot('2026-11-01',30)->'days') d where d->>'user_id'<>(select s::text from f)));
with deleted as (delete from public.vihem_snow_availability returning user_id) select pg_temp.expect('driver direct delete affects no rows',count(*)=0) from deleted;
reset role;
update public.vihem_profiles set snow_time_access=false where id=(select s from f);
set local role authenticated;
select pg_temp.reject('on-call-only account cannot enter calendar',$q$select public.vihem_snow_availability_snapshot('2026-11-01',30)$q$);
reset role;
update public.vihem_profiles set snow_time_access=true,active=false where id=(select s from f);
set local role authenticated;
select pg_temp.reject('inactive driver denied',$q$select public.vihem_snow_availability_snapshot('2026-11-01',30)$q$);
reset role;
ROLLBACK;
